/// <summary>
/// MPJ_3747_AltVendorPayee 06/03/2021 Nathan Ciantar
/// returns the field found
/// </summary>
/// <returns>metOrganisation</returns>
public display METOrganisation displayMETOrganisation()
{
    return VendBankAccount::find(this.AccountNum, this.BankAccount).METVendorBankOrganisation;
}

/// <summary>
/// MPJ_3747_AltVendorPayee 06/03/2021 Nathan Ciantar
/// returns the field found
/// </summary>
/// <returns>metSupplyChain</returns>
public display NoYes displayMETAltVendPayee()
{
    return VendBankAccount::find(this.AccountNum, this.BankAccount).METAltVendorPayee;
}

    /// <summary>
    /// MPJ_15748_VendorList
    /// </summary>
    /// <returns>
    /// returns vendor address
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    public  display LogisticsAddressing displayMETVendAddress()
    {
        DirPartyTable           metDirPartyTable;
        DirPartyLocation        metDirPartyLocation;
        DirPartyLocationRole    metDirPartyLocationRole;
        LogisticsLocationRole   metLogisticsLocationRole;
        LogisticsLocation       metLogisticsLocation;
        LogisticsPostalAddress  metLogisticsPostalAddress;

        select firstonly RecId from metDirPartyTable
             where metDirPartyTable.RecId == this.Party
         join IsPrimary from metDirPartyLocation
             where metDirPartyLocation.Party == this.Party
         join metDirPartyLocationRole
             where metDirPartyLocationRole.PartyLocation == metDirPartyLocation.RecId
         join Type from metLogisticsLocationRole
             where metLogisticsLocationRole.RecId == metDirPartyLocationRole.LocationRole
         join metLogisticsLocation
             where metLogisticsLocation.RecId == METdirPartyLocation.Location
         join metLogisticsPostalAddress
             where metLogisticsPostalAddress.Location == metLogisticsLocation.RecId;

        return metLogisticsPostalAddress.Address;
    }

/// <summary>
/// MPJ_15748_VendorList
/// </summary>
/// <returns>
/// returns Main AccountId 
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display VendBankAccountId displayMETAccountId()
{
    VendBankAccount metVendBankAccount;
   
    select firstonly AccountID from metVendBankAccount
        order by AccountID desc
        where metVendBankAccount.VendAccount == this.AccountNum;
    return metVendBankAccount.AccountID;
}

    /// <summary>
    /// MPJ_15748_VendorList
    /// </summary>
    /// <returns>
    /// returs Bank Name
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display Name displayMETBankAccountName()
    {
        VendBankAccount metVendBankAccount;

        select firstonly Name from metVendBankAccount
            where metVendBankAccount.VendAccount == this.AccountNum
            &&    metVendBankAccount.AccountID  == 'Main';

        return metVendBankAccount.Name;
    }

/// <summary>
/// MPJ_15748_VendorList
/// </summary>
/// <returns>
/// return Alternate Bank AccountId
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display VendBankAccountId displayMETAlternateAccountId()
{
    VendBankAccount metVendBankAccount;
   
    select firstonly AccountID from METvendBankAccount
        where metVendBankAccount.VendAccount == this.AccountNum
        &&    metVendBankAccount.AccountID   != 'Main'
        &&    (metVendBankAccount.ExpiryDate == Global::utcDateTimeNull() || metVendBankAccount.ExpiryDate > DateTimeUtil::utcNow()) ;

    return metVendBankAccount.AccountID;
}

