    /// <summary>
    /// MPJ_15748_VendorList
    /// </summary>
    /// <returns>
    /// returns Alternate Bank Account METAltVendorPayee
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display NoYes displayMETAltBankVendPayee()
    {
        VendBankAccount metVendBankAccount;

        select firstonly METAltVendorPayee from metVendBankAccount
            where metVendBankAccount.VendAccount == this.AccountNum
            &&    metVendBankAccount.AccountID   != 'Main'
            &&    (metVendBankAccount.ExpiryDate == Global::utcDateTimeNull() || metVendBankAccount.ExpiryDate > DateTimeUtil::utcNow()) ;

        return metVendBankAccount.METAltVendorPayee;
        
    }
